package solution
import("sort";"strconv";"strings")
func pv(s string)([3]int,bool){var o [3]int;p:=strings.Split(s,".");if len(p)!=3{return o,false};for i,x:=range p{v,e:=strconv.Atoi(x);if e!=nil||v<0||v>1000000||strconv.Itoa(v)!=x{return o,false};o[i]=v};return o,true}
func vl(a,b [3]int)bool{for i:=0;i<3;i++{if a[i]!=b[i]{return a[i]<b[i]}};return false}
func VersionSelection(s string)(string,bool){p:=strings.Split(s,";");if len(p)!=2||p[1]==""{return "",false};c,ok:=pv(p[0]);if !ok{return "",false};a:=[][3]int{};seen:=map[[3]int]bool{};for _,x:=range strings.Split(p[1],","){v,ok:=pv(x);if !ok||seen[v]{return "",false};seen[v]=true;if v==c||vl(v,c){a=append(a,v)}};if len(a)==0{return "",true};sort.Slice(a,func(i,j int)bool{return vl(a[i],a[j])});v:=a[len(a)-1];return strconv.Itoa(v[0])+"."+strconv.Itoa(v[1])+"."+strconv.Itoa(v[2]),true}
